import{d as r,C as s,o as g,c as h,a3 as e,E as i,j as a,a as c}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第十四章","description":"《正易心法》第十四章——钻木凿井，人之坎离：坎离为日月之体、天地中气，日月交错生三百六十爻诸卦；辨体用，破所见，归于穷理尽性。","frontmatter":{"title":"正易心法·第十四章","description":"《正易心法》第十四章——钻木凿井，人之坎离：坎离为日月之体、天地中气，日月交错生三百六十爻诸卦；辨体用，破所见，归于穷理尽性。","category":"guide","aliases":["正易心法第十四章","钻木凿井人之坎离","坎离日月"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-14.md","filePath":"yijing/zheng-yi-xin-fa/chapter-14.md","lastUpdated":1790647676000}'),d={name:"yijing/zheng-yi-xin-fa/chapter-14.md"},v=r({...d,setup(u){const t=[{id:"z14-01",label:"一、识取自然",showLabel:!0,sentences:[["钻木凿井，人之坎离。天地坎离，",{text:"识取自然",glossary:"shiquZiran"},"。"]],note:["钻木取火、凿地取水，是人工制造的坎离；天地之间的坎离，要认识并取法自然。（人工的坎离是「用」，天地的坎离是「体」——这一句是全章的纲：**不要把注意力放在可以制造的坎离上，要看那个本来就在的坎离。**）"]},{id:"z14-02",label:"二、乾一阴升为离",showLabel:!0,sentences:[["乾，天也。一阴升于乾之中为离。离为日，则曰",{text:"本天之气",glossary:"bentianZhiqi"},"也。"]],note:["乾是天。一阴升入乾的中爻，形成离。离对应太阳，所以说太阳根本于天（乾）之气。（注意方向：**「升」——坤阴上升入乾**，这是离的生成；与第九章「一阴杂于中」是同一件事，本章从「升入」的角度再说一遍。）"]},{id:"z14-03",label:"三、坤一阳降为坎",showLabel:!0,sentences:[["坤，地也。一阳下降于坤之中为坎。坎为月，则曰",{text:"本地之气",glossary:"bendiZhiqi"},"也。"]],note:["坤是地。一阳降入坤的中爻，形成坎。坎对应月亮，所以说月亮根本于地（坤）之气。（**「降」——乾阳下降入坤**，这是坎的生成。第十三章说坎是「乾水」、是「气之液」，本章给出它的宇宙论定位：坎为月，是地气中含天光。）"]},{id:"z14-04",label:"四、日月交错生诸卦",showLabel:!0,sentences:[["日为天气，自西而下以交于地。月为地气，自东而上以交于天。日月交错，一昼一夜，循环三百六十度，而扰扰万绪起矣，是为三百六十爻，而诸卦生焉。"]],note:["太阳是天气，从西方下落以交于地；月亮是地气，从东方上升以交于天。日月交错，一昼一夜，循环三百六十度，纷繁复杂的万事万物由此而起——这就是三百六十爻，诸卦由此而生。（这是《正易心法》的**宇宙生成论核心**：不是「圣人画卦」，而是「日月运行自然生卦」。一昼一夜就是一次完整的阴阳交媾。）"]},{id:"z14-05",label:"五、坎离天地中气",showLabel:!0,sentences:[["坎离日月，天地之",{text:"中气",glossary:"zhongqi"},"也。"]],note:["坎离日月，是天地的中气（枢纽）。（「中气」一词极准：坎离不是天地的两极，而是**天地之间交通的媒介**——乾阳降到坤中为坎，坤阴升到乾中为离，日月就是天地互相往来的那两个使者。）"]},{id:"z14-06",label:"六、体用之辨",showLabel:!0,sentences:[["仲尼特言水火，而不言日月者，日月其",{text:"体",glossary:"tiyong"},"也，水火其用也。言其用而不言其体，盖欲其设施之广而无碍也。学者不悟，但求之于钻木凿井之间，所失益甚矣。"]],note:["孔子（《系辞传》）只说水火而不说日月，是因为日月是体，水火是用；说用而不说体，是为了让应用广泛而不受限制。学者不能领悟，只在钻木凿井（普通水火）上求坎离，所失就更严重了。（孔子说水火的好处：**说「日月」只能想到天文现象；说「水火」则可以推广到自然水火、人体肾水心火、炼丹铅汞、社会柔刚——「设施之广而无碍」。** 但代价是：学者忘了日月之体。）"]},{id:"z14-07",label:"七、男女构精之象",showLabel:!0,sentences:[["又论，月上于天，日入于地，男女构精之象。一来一往，卦画有",{text:"中通",glossary:"zhongtong"},"之象。此所谓观于",{text:"卦脉",glossary:"guamai"},"，理则昭然也。"]],note:["再论：月亮升于天，太阳入于地，这是男女交合构精的象。一来一往，卦画中有中间贯通的象。（「中通」指坎离的中爻：**离的中爻是阴（虚），可以接纳；坎的中爻是阳（实），可以给予**——坎中之阳填入离中之虚，正是「取坎填离」的宇宙原型，也是「月光来自太阳」的道理。这一句又把第七章的「卦脉」接上了。）"]},{id:"z14-08",label:"八、破所见而穷理尽性",showLabel:!0,sentences:[["有谓理实昭然，若山者自天之坠也。《传》曰：“自有宇宙，便有此山。”又曰：“星陨为石。”推此意，则山自天坠无疑。而世曰：“山者，地之物。”以所见者言之耳。至月风雷雨，皆自地出也。而世曰：“月风雷雨，天之物。”亦以所见者言之耳。世以所见如此！苟徇其所见，则天地万物，皆所不晓。审知《易》者，所以",{text:"穷理尽性",glossary:"qionglijinxing"},"也。学者不可不留意邪！"]],note:["（末段是全书认识论批判的顶点。）道理确实昭然，比如山是从天上坠落的：《传》说「自有宇宙，便有此山」，又说「星陨为石」——推此意，山自天坠无疑。而世人说「山是地上的东西」，不过是以眼睛所见来说而已。至于月、风、雷、雨，都是从地中出来的；而世人说它们是「天上的东西」，同样以所见为准。世人都以所见为准！若只顺从眼睛所见，则天地万物都无法真正了解。**真正懂得《易》的人，正是用来穷究事物之理、完全实现本性的。**（「穷理尽性」语出《说卦传》：《易》的最终目的不是算卦预测，而是穷究万物之理、进而实现自己的本性——**穷理是手段，尽性是目的**。这也回收了第一章「山自天上而坠」的钩子。）"]}],l=[{id:"shiquZiran",term:"识取自然",pinyin:"shí qǔ zì rán",meaning:"认识并取法自然。天地坎离才是根本，人工（钻木凿井）是末。"},{id:"bentianZhiqi",term:"本天之气",pinyin:"běn tiān zhī qì",meaning:"根本于天（乾）的气。离虽有阴，本质是乾阳外显，故为日。"},{id:"bendiZhiqi",term:"本地之气",pinyin:"běn dì zhī qì",meaning:"根本于地（坤）的气。坎虽有阳，本质是坤阴内藏，故为月。"},{id:"zhongqi",term:"中气",pinyin:"zhōng qì",meaning:"天地之间的枢纽之气。坎离居中，是天地交通的媒介。"},{id:"tiyong",term:"体与用",pinyin:"tǐ yǔ yòng",meaning:"日月是体（本质、根源），水火是用（功能、应用）。孔子言水火不言日月，是为「设施之广而无碍」。"},{id:"zhongtong",term:"中通",pinyin:"zhōng tōng",meaning:"中间贯通的象。离之中爻虚可纳，坎之中爻实可予——坎中之阳填入离中之虚。"},{id:"guamai",term:"卦脉",pinyin:"guà mài",meaning:"卦画的内在脉络。第七章核心概念，本章再次点出（「观于卦脉，理则昭然」）。"},{id:"qionglijinxing",term:"穷理尽性",pinyin:"qióng lǐ jìn xìng",meaning:"穷究事物之理，完全实现本性。语出《说卦传》，是易学的最高目标：穷理是手段，尽性是目的。"}];return(b,n)=>{const p=s("DaoTextReading"),o=s("DaoKeywordCards");return g(),h("div",null,[n[0]||(n[0]=e(`<h1 id="正易心法·第十四章" tabindex="-1">正易心法·第十四章 <a class="header-anchor" href="#正易心法·第十四章" aria-label="Permalink to &quot;正易心法·第十四章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章有三个层次，是全书的<strong>宇宙论高峰</strong>：</p><p><strong>第一层（宇宙论）：坎离是日月，日月交错生万卦</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>坎（月）= 地气上升交天</span></span>
<span class="line"><span>离（日）= 天气下降交地</span></span>
<span class="line"><span>日月一昼夜循环 = 阴阳一次完整交媾</span></span>
<span class="line"><span>                 = 三百六十爻 = 诸卦生焉</span></span></code></pre></div><p><strong>这是《正易心法》的宇宙生成论核心：不是「圣人画卦」，而是「日月运行自然生卦」。</strong></p><p><strong>第二层（方法论）：体用之辨，不可执用忘体</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>日月 = 体（坎离的本质）</span></span>
<span class="line"><span>水火 = 用（坎离的应用）</span></span></code></pre></div><p>孔子说水火，是为了应用广泛；但学者只知水火，忘了日月之体——就是「钻木凿井」的错误。</p><p><strong>第三层（认识论）：破除「以所见为准」的局限</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>山看起来在地上 → 本质来自天</span></span>
<span class="line"><span>月看起来在天上 → 本质来自地</span></span></code></pre></div><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>「中通之象」——坎离的中爻</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>离☲ 中爻是阴（虚）→ 可以接纳</span></span>
<span class="line"><span>坎☵ 中爻是阳（实）→ 可以给予</span></span>
<span class="line"><span></span></span>
<span class="line"><span>坎中之阳 → 填入 → 离中之虚</span></span>
<span class="line"><span>= 月光来自太阳（坎中阳来自乾）</span></span>
<span class="line"><span>= 内丹「取坎填离」的宇宙原型</span></span></code></pre></div><p><strong>「山自天坠」的卦画逻辑</strong>（回收第一章的钩子）：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>艮☶ = 一阳在二阴上 = 乾上爻（天的最高处）落入坤中</span></span>
<span class="line"><span>   = 天上之气凝止于上</span></span>
<span class="line"><span>   = 天上之物坠落，凝固为山</span></span>
<span class="line"><span></span></span>
<span class="line"><span>物理验证（麻衣引）：</span></span>
<span class="line"><span>  星陨为石 → 天上之物（星）坠落为地上之物（石）</span></span>
<span class="line"><span>  山 = 大规模的「星陨为石」</span></span></code></pre></div><p><strong>这不是神话，而是卦画逻辑的自然推论。</strong></p><p><strong>「穷理尽性」的认识论意义</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>穷理：穷究事物的本质之理 → 不被表象迷惑</span></span>
<span class="line"><span>尽性：完全实现自己的本性 → 尽乾为圣，尽坤为贤</span></span>
<span class="line"><span>穷理是手段，尽性是目的</span></span></code></pre></div><p><strong>《易》的最终目的</strong>：不是算卦预测，不是背诵卦辞，而是<strong>通过卦画穷究万物之理，进而实现自己的本性 = 圣贤之学。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先读「日月交错 → 三百六十爻 → 诸卦生焉」——这是全书最要紧的一段宇宙生成论；</li><li>再读「体用之辨」——<strong>记住「钻木凿井」是贬义</strong>；</li><li>最后读末段——<strong>「世以所见如此」这四个字，是麻衣对常识最重的一次批评。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>人之坎离</strong>：钻木凿井是人工，天地坎离才是本。</li><li><strong>离为日</strong>：乾中入阴，本天之气。</li><li><strong>坎为月</strong>：坤中入阳，本地之气。</li><li><strong>日月生卦</strong>：一昼夜一圈，三百六十爻，诸卦生焉。</li><li><strong>坎离中气</strong>：天地交通的媒介。</li><li><strong>体用之辨</strong>：日月为体，水火为用。</li><li><strong>中通之象</strong>：坎实离虚，取坎填离。</li><li><strong>穷理尽性</strong>：破除所见之蔽，是《易》的最终目的。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,25)),i(p,{colophon:"识取自然 · 日月生卦 · 体用之辨 · 穷理尽性",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第十四章原文",sections:t,glossary:l}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入，用字随底本，不作统一。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[c("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),i(o,{items:[{term:"天地坎离",pinyin:["kǎn","lí"],meaning:"坎离是日月之体、天地中气：离为日（本天之气），坎为月（本地之气）。人工的钻木凿井只是其「用」。"},{term:"日月生卦",pinyin:["rì","yuè"],meaning:"日月交错、一昼一夜、循环三百六十度＝三百六十爻，诸卦生焉。卦是日月运行自然生成，非圣人创造。"},{term:"体用之辨",pinyin:["tǐ","yòng"],meaning:"日月为体，水火为用。孔子言水火不言日月，是为应用广泛；但学者执用忘体，便成了「钻木凿井」。"},{term:"中通之象",pinyin:["zhōng","tōng"],meaning:"离之中爻虚可纳，坎之中爻实可予——坎中之阳填入离中之虚，即「取坎填离」的宇宙原型。"},{term:"山自天坠",pinyin:["shān","zì"],meaning:"艮＝一阳在二阴上＝乾上爻落入坤中，故山自天坠。以「星陨为石」为验证。回收第一章钩子。"},{term:"穷理尽性",pinyin:["qióng","lǐ"],meaning:"《说卦传》语，是《易》的最终目的：穷究万物之理（去表象之蔽），完全实现本性（尽乾为圣、尽坤为贤）。"}]}),n[3]||(n[3]=e(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是全书<strong>宇宙论的高峰</strong>，三个层次一气贯通：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>宇宙论：坎离是日月，日月交错 → 三百六十爻 → 诸卦生焉</span></span>
<span class="line"><span>方法论：日月为体，水火为用；执用忘体即「钻木凿井」</span></span>
<span class="line"><span>认识论：破除「以所见为准」——山自天来，月风雷雨自地出</span></span></code></pre></div><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>为什么日月交错能生三百六十爻？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>太阳一年约 365 天（近 360 度）</span></span>
<span class="line"><span>月亮一月约 30 天，一年 12 个月</span></span>
<span class="line"><span>日月交错的节点 ≈ 每天一次</span></span>
<span class="line"><span>= 一年约 360 次阴阳交媾 = 360 爻</span></span></code></pre></div><p><strong>麻衣的意思</strong>：卦爻的数目不是圣人随意规定的，而是<strong>日月运行的自然节律决定的</strong>——这是第五章「合为自然」的宇宙论根据。</p><p><strong>「山自天坠」的逻辑链</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>乾上爻 = 天的最高处</span></span>
<span class="line"><span>这一爻落入坤（地）中，凝止于上</span></span>
<span class="line"><span>= 天上之物坠落，凝固为山</span></span>
<span class="line"><span>= 艮（止）的本质：天气凝止</span></span>
<span class="line"><span>物理验证：星陨为石</span></span></code></pre></div><p><strong>「穷理尽性」的认识论意义</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>穷理：不被表象（所见）迷惑——山不是「地之物」，月不是「天之物」</span></span>
<span class="line"><span>尽性：完全实现自己的本性——尽乾为圣，尽坤为贤</span></span>
<span class="line"><span>穷理是手段，尽性是目的</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>读「日月生卦」那一句要慢：<strong>它把「圣人画卦」换成了「日月生卦」</strong>；</li><li>记住「钻木凿井」是麻衣的<strong>贬词</strong>：只知用不知体；</li><li>最后读末段的一句自问：<strong>我判断一件事的「来源」，是靠眼睛看的方向，还是靠它的结构？</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>钻木取火、凿地取水，是人工制造的坎离；天地之间的坎离，要认识并取法自然。</p><p>乾是天。一阴升入乾的中爻，形成离。离对应太阳，所以说太阳根本于天之气。</p><p>坤是地。一阳降入坤的中爻，形成坎。坎对应月亮，所以说月亮根本于地之气。</p><p>太阳是天气，从西方下落以交于地；月亮是地气，从东方上升以交于天。日月交错，一昼一夜，循环三百六十度，纷繁复杂的万事万物由此而起——这就是三百六十爻，诸卦由此而生。</p><p>坎离日月，是天地的中气。</p><p>孔子只说水火而不说日月，是因为日月是体、水火是用；说用而不说体，是为了让应用广泛而不受限制。学者不能领悟，只在钻木凿井上求坎离，所失就更严重了。</p><p>再论：月亮升于天，太阳入于地，这是男女交合构精的象。一来一往，卦画中有中间贯通的象。这就是所谓「观于卦脉，理则昭然」。</p><p>道理确实昭然，比如山是从天上坠落的。《传》说「自有宇宙，便有此山」，又说「星陨为石」——推此意，山自天坠无疑。而世人说「山是地上的东西」，不过是以眼睛所见来说而已。至于月、风、雷、雨，都是从地中出来的；而世人说它们是「天上的东西」，同样以所见为准。</p><p>世人都以所见为准！若只顺从眼睛所见，则天地万物都无法真正了解。真正懂得《易》的人，正是用来穷究事物之理、完全实现本性的。学者不可不留意啊！</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第十四章是全书的高峰——<strong>它把坎离从「两个卦」提升为「日月的身体」，于是诸卦不再是圣人画的，而是日月跑出来的。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「钻木凿井，人之坎离」</strong>——开篇就把人工摆在了次要的位置。<strong>我能造的火和水，只是坎离的「用」；真正的坎离在天上跑。</strong> 这个次序感很重要：<strong>先抬头，再低头。</strong></li><li><strong>「日月交错，三百六十爻，诸卦生焉」</strong>——这是全书最重的一句。<strong>卦不是被创造的，是被生出来的。</strong> 那么我读卦时，是在读一个符号，还是在读某一天某一刻的日月状态？</li><li><strong>「体用之辨」</strong>——孔子说水火是为了「设施之广」，代价是后人忘了日月。<strong>这就是「用」发达而「体」隐没的过程。</strong> 我平时是不是也这样：工具越用越熟，源头越忘越远？</li><li><strong>「中通之象」</strong>——离中虚、坎中实，一纳一予。<strong>「取坎填离」这四个字，原来是这个意思：把实给虚，把下给上。</strong></li><li><strong>末段的「世以所见如此」</strong>——这是全书对常识最重的一次批评。<strong>山在地上、月在天上——所见如此，本质却不是。</strong> 那么：<strong>我判断一件事的来源，靠的是它看起来在哪儿，还是它从哪儿来？</strong></li><li><strong>「穷理尽性」</strong>——收在《说卦传》的四个字上。<strong>《易》的终点不是算得准，是活得明白。</strong></li><li><strong>钩子已收</strong>：第一章的「山自天上而坠」，到这里正式收官——<strong>卦脉的必然推论，不是神话。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-01">第一章 · 羲皇易道</a> — 「山自天上而坠」（本章回收此钩子）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-07">第七章 · 观于卦脉</a> — 「观于卦脉，理则昭然」（本章重申）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-13">第十三章 · 坎兑二水</a> — 坎为乾水（本章给出宇宙论定位：坎为月）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-11">第十一章 · 偏陂反侧</a> — 「炼」（中通之象即「取坎填离」的原型）</li><li><a href="/Dao/yijing/shi-yi/shuo-gua-zhuan">说卦传</a> — 「穷理尽性」所出，及八卦物象的索引</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「水火相逮」：麻衣据此辨体用（日月为体，水火为用）</li></ul>`,30))])}}});export{y as __pageData,v as default};
